def quantlet_intro(name, text):
    if name not in QUANTLET_INTROS:
        return text
    before, after = QUANTLET_INTROS[name]
    if text == after:
        return text
    if text != before:
        raise ValueError(f"Unexpected Ch18 intro for {name}")
    return after


_MASTER_HITS = {}


def begin_master(kind, lang):
    for key in MASTER_CELLS:
        if key.endswith('|' + kind + '|' + lang):
            _MASTER_HITS[key] = 0


def master_cell(text, typ, kind, lang):
    key = '|'.join((typ, kind, lang))
    pair = MASTER_CELLS.get(key)
    if pair is None:
        return text
    before, after = pair
    if text == before or text == after:
        _MASTER_HITS[key] += 1
        return after
    return text


def end_master(kind, lang):
    bad = [key for key in MASTER_CELLS
           if key.endswith('|' + kind + '|' + lang) and _MASTER_HITS.get(key) != 1]
    if bad:
        raise ValueError(f"Ch18 master cells not matched exactly once: {bad}")
